from pathlib import Path
p=Path('workspace.js');s=p.read_text(encoding='utf-8-sig');start=s.index('taskRow=function(t)');end=s.index('function welcomeStrip()',start)
s=s[:start]+'''function focusedTimeLabel(seconds){return seconds<=0?'Not started':seconds<60?`${Math.max(1,Math.round(seconds))} sec`:`${Math.round(seconds/60)} min`;}
taskRow=function(t){const kind=t.kind||'task';return `<div class="task-card"><div class="task thought-task ${t.done?'done':''}"><input aria-label="Complete ${esc(t.title)}" type="checkbox" data-complete="${t.id}" ${t.done?'checked':''}><div class="task-body"><span dir="auto">${esc(t.title)}</span><small><span class="kind-tag">${esc(kind)}</span>${t.dueDate?` · Due ${esc(t.dueDate)}`:''}</small>${kind==='task'?`<div class="thought-time"><label>Planned time <input type="number" min="5" max="1440" step="5" value="${t.estimate||30}" data-estimate="${t.id}" aria-label="Estimated minutes for ${esc(t.title)}"><span>min</span></label><span class="thought-actual">Time focused: <strong>${focusedTimeLabel(taskSeconds(state,t.id))}</strong></span></div>`:''}</div><div class="thought-actions"><button class="edit-task" data-edit-task="${t.id}" aria-label="Edit ${esc(t.title)}">✎ Edit</button>${kind==='task'&&!t.done&&!['drop','delegate'].includes(t.quadrant)?`<button class="task-focus" data-focus="${t.id}">Start focus</button>`:''}<button class="star ${t.highlight===dayKey()?'selected':''}" data-star="${t.id}" aria-label="Toggle daily highlight">☆</button><select aria-label="Prioritize ${esc(t.title)}" data-move="${t.id}">${Object.entries(quadrants).map(([k,v])=>`<option value="${k}" ${k===t.quadrant?'selected':''}>${v}</option>`).join('')}</select><button class="icon" data-delete="${t.id}" aria-label="Delete ${esc(t.title)}">×</button></div></div>${t.nextSteps?.length?`<div class="substeps">${t.nextSteps.map(step=>`<label><input type="checkbox" data-step-task="${t.id}" data-step="${step.id}" ${step.done?'checked':''}><span class="${step.done?'checked-step':''}" dir="auto">${esc(step.title)}</span></label>`).join('')}</div>`:''}</div>`;};
''' + s[end:];p.write_text(s,encoding='utf-8')
